const item = $json;

function decodeBase64Url(data = '') {
  if (!data) return '';
  let normalized = data.replace(/-/g, '+').replace(/_/g, '/');
  while (normalized.length % 4) normalized += '=';
  return Buffer.from(normalized, 'base64').toString('utf8');
}

function extractBodiesFromPayload(payload) {
  const bodies = [];

  function walk(part) {
    if (!part) return;

    const mimeType = part.mimeType || '';
    const data = part.body?.data;

    if (data) {
      bodies.push({
        mimeType,
        content: decodeBase64Url(data),
      });
    }

    if (Array.isArray(part.parts)) {
      for (const child of part.parts) {
        walk(child);
      }
    }
  }

  walk(payload);
  return bodies;
}

function htmlToText(input = '') {
  return String(input)
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/p>/gi, '\n')
    .replace(/<\/div>/gi, '\n')
    .replace(/<\/tr>/gi, '\n')
    .replace(/<\/td>/gi, '\n')
    .replace(/<\/th>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&')
    .replace(/&#39;/g, "'")
    .replace(/&quot;/g, '"')
    .replace(/\r/g, '')
    .replace(/[ \t]+/g, ' ')
    .replace(/\n\s+/g, '\n')
    .replace(/\n{2,}/g, '\n')
    .trim();
}

function sqlSafe(value) {
  return String(value || '')
    .replace(/\\/g, '\\\\')
    .replace(/'/g, "\\'")
    .trim();
}

function cleanValue(value = '') {
  return String(value || '')
    .replace(/\s+:\s*$/g, '')
    .replace(/^:\s*/g, '')
    .trim();
}

function getHeader(name) {
  const target = name.toLowerCase();

  if (Array.isArray(item.payload?.headers)) {
    const header = item.payload.headers.find(h =>
      String(h.name || '').toLowerCase() === target
    );
    if (header?.value) return header.value;
  }

  if (item.headers && typeof item.headers === 'object') {
    const foundKey = Object.keys(item.headers).find(k =>
      k.toLowerCase() === target
    );

    if (foundKey) {
      return String(item.headers[foundKey])
        .replace(new RegExp(`^${name}:\\s*`, 'i'), '')
        .trim();
    }
  }

  return '';
}

const bodies = extractBodiesFromPayload(item.payload);

const rawCandidates = [
  item.text,
  item.textPlain,
  item.plain,
  item.html,
  item.textHtml,
  item.body,
  item.payload?.body?.data ? decodeBase64Url(item.payload.body.data) : '',
  ...bodies.map(b => b.content),
].filter(Boolean);

const rawBody = rawCandidates.join('\n\n');
const textContent = htmlToText(rawBody);

const labels = [
  'First Name',
  'Last Name',
  'Email',
  'Phone Number',
  'Country/Region',
  'State/Region',
  'City',
  'LinkedIn URL',
  'Job title',
  'Education',
  'CV',
  'Source',
  'I added hr@example.com',
];

function normalizeLabel(value = '') {
  return String(value || '')
    .replace(/\s*:\s*$/g, '')
    .trim()
    .toLowerCase();
}

const lines = textContent
  .split('\n')
  .map(line => line.trim())
  .filter(Boolean);

function isKnownLabel(line) {
  const normalized = normalizeLabel(line);
  return labels.some(label => normalizeLabel(label) === normalized);
}

function getField(label) {
  const wanted = normalizeLabel(label);

  for (let i = 0; i < lines.length; i++) {
    const current = normalizeLabel(lines[i]);

    if (current === wanted) {
      for (let j = i + 1; j < lines.length; j++) {
        if (!lines[j]) continue;
        if (isKnownLabel(lines[j])) return '';
        return cleanValue(lines[j]);
      }
    }

    // fallback لو HubSpot رجّعها بنفس السطر مثل: First Name: Abdullah
    const sameLineRegex = new RegExp(`^${label.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}\\s*:\\s*(.+)$`, 'i');
    const sameLineMatch = lines[i].match(sameLineRegex);
    if (sameLineMatch) {
      return cleanValue(sameLineMatch[1]);
    }
  }

  return '';
}

function extractCvFilename() {
  const fromLink =
    String(rawBody).match(/CV[\s\S]{0,300}?<a[^>]*>(.*?)<\/a>/i)?.[1] ||
    String(rawBody).match(/<a[^>]*>([^<]*\.pdf)<\/a>/i)?.[1];

  if (fromLink) return cleanValue(fromLink);

  const cvField = getField('CV');

  if (!cvField) return '';

  // مثال:
  // my_cv-(1)-2549c9.pdf:https://api-na1.hubspot.com/...
  const pdfMatch = cvField.match(/([^\/\s:]+\.pdf)/i);
  if (pdfMatch) return cleanValue(pdfMatch[1]);

  return cleanValue(cvField.split(':')[0]);
}

const dateHeader = getHeader('Date');
const messageIdHeader = getHeader('Message-ID');
const fromHeader = getHeader('From');

return {
  message_id: sqlSafe(item.id || ''),
  hubspot_message_id: sqlSafe(item.messageId || messageIdHeader || ''),
  thread_id: sqlSafe(item.threadId || ''),
  received_at: item.date
    ? new Date(item.date).toISOString()
    : dateHeader
      ? new Date(dateHeader).toISOString()
      : '',
  from_email: sqlSafe(item?.from?.value?.[0]?.address || fromHeader || ''),

  first_name: sqlSafe(getField('First Name')),
  last_name: sqlSafe(getField('Last Name')),
  applicant_email: sqlSafe(getField('Email')).toLowerCase(),
  phone: sqlSafe(getField('Phone Number')),
  country: sqlSafe(getField('Country/Region')),
  state: sqlSafe(getField('State/Region')),
  city: sqlSafe(getField('City')),
  linkedin_url: sqlSafe(getField('LinkedIn URL')),
  job_title: sqlSafe(getField('Job title')),
  education: sqlSafe(getField('Education')),
  cv_filename: sqlSafe(extractCvFilename()),
  source: sqlSafe(getField('Source')),

  debug_body_length: textContent.length,
  debug_body_preview: textContent.slice(0, 1000),
};

// Data from ParseHubSpotForm node
const applicant = $('ParseHubSpotForm').first().json;

// Data from the Send (First Email) Gmail node
// This is the thread we will reply to forever
const sentEmail = $('Send (First Email)').first().json;

const threadId = sentEmail.threadId || '';
const messageId = sentEmail.id || '';

// applied_at: when they submitted the form
const appliedAt = applicant.received_at
  ? new Date(applicant.received_at).toISOString().slice(0, 19).replace('T', ' ')
  : new Date().toISOString().slice(0, 19).replace('T', ' ');

// Clean the linkedin_url — strip HTML tags if present
const cleanLinkedin = (applicant.linkedin_url || '')
  .replace(/<a[^>]*>(.*?)<\/a>/gi, '$1')
  .replace(/<br>/gi, '')
  .trim();

return {
  // Identity fields
  first_name:       applicant.first_name,
  last_name:        applicant.last_name,
  applicant_email:  applicant.applicant_email,
  phone:            applicant.phone || null,
  country:          applicant.country || null,
  state:            applicant.state || null,
  city:             applicant.city || null,
  linkedin_url:     cleanLinkedin || null,
  job_title:        applicant.job_title || null,
  education:        applicant.education || null,
  cv_filename:      applicant.cv_filename || null,
  source:           applicant.source || null,

  // Pipeline state — always starts as 'new'
  status:           'new',
  blacklisted:      0,

  // Gmail threading — from the SENT email, not the HubSpot notification
  thread_id:        threadId,
  message_id:       messageId,

  // Timestamps
  applied_at:       appliedAt
};
